"""Stand-in answer matrices, so track A can exercise the pipeline before track B.

These are **not systems and not gauge blocks**. They are placeholder answer
matrices in contract 5.4 format whose only purpose is to give the pair-testing,
rank-preservation and characterisation code something with per-video variation
to chew on while track B's real systems are being built. Their system cards say
so in the ``description`` field, and their family is ``standin`` so that nothing
downstream can mistake them for an audited system. Delete them from any run that
produces reportable numbers.

    python -X utf8 tests/fixtures/make_standins.py --manifest M --out outputs/answers
"""

from __future__ import annotations

import argparse
import math
import os
import sys

import numpy as np
import pandas as pd

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if REPO_ROOT not in sys.path:
    sys.path.insert(0, REPO_ROOT)

from ape.classes import N_CLASSES, wrong_class  # noqa: E402
from ape.metrics import PROB_COLS  # noqa: E402
from ape.protocol import load_manifest  # noqa: E402

# name -> (median lock delay, spread of the delay, share that never locks,
#          oscillation period or None, confidence)
STANDIN_SPECS = {
    "standin_early": (1.0, 0.8, 0.05, None, 0.85),
    "standin_late": (3.2, 1.2, 0.15, None, 0.80),
    "standin_flippy": (2.5, 1.0, 0.10, 0.5, 0.70),
    "standin_smoothed": (2.0, 0.6, 0.08, None, 0.88),
}


def build_one(manifest: pd.DataFrame, name: str, delta_fine_s: float,
              span_s: float, pad_s: float, seed: int) -> pd.DataFrame:
    med, spread, never, period, conf = STANDIN_SPECS[name]
    rng = np.random.default_rng(seed)
    j_min = -int(math.ceil(pad_s / delta_fine_s))
    j_max = int(math.ceil((span_s + pad_s) / delta_fine_s))
    js = np.arange(j_min, j_max + 1, dtype=np.int64)
    frames = []
    for row in manifest.itertuples(index=False):
        y = int(row.class_code)
        w = wrong_class(y)
        d0 = float(rng.normal(med, spread))
        if rng.uniform() < never:
            d0 = float("inf")
        delta = js.astype(float) * delta_fine_s
        if period is None:
            pred = np.where(delta >= d0, y, w)
        else:
            alt = np.where(np.mod(np.floor(delta / period), 2.0) == 0.0, w, y)
            pred = np.where(delta >= d0, y, alt)
        piece = pd.DataFrame(
            {"video_id": str(row.video_id), "j": js,
             "delta_s": float(delta_fine_s), "pred": pred.astype(np.int64)}
        )
        probs = np.full((len(js), N_CLASSES), (1.0 - conf) / (N_CLASSES - 1))
        probs[np.arange(len(js)), pred.astype(int)] = conf
        for c, col in enumerate(PROB_COLS):
            piece[col] = probs[:, c]
        piece["committed"] = False
        frames.append(piece)
    return pd.concat(frames, ignore_index=True)


def card(name: str) -> dict:
    med, spread, never, period, conf = STANDIN_SPECS[name]
    return {
        "system_id": name,
        "family": "standin",
        "description": (
            "PLACEHOLDER answer matrix generated by a rule, used only to exercise "
            "the protocol pipeline before track B's systems exist. Not a model, "
            "not an audited system, not a gauge block. Never report its numbers."
        ),
        "backbone": None,
        "trained_on_split": None,
        "dev_tuned_params": None,
        "train_data_unknown": False,
        "cost_note": "negligible",
        "causal": True,
        "parent_system_id": None,
        "standin_params": {
            "median_lock_s": med, "lock_spread_s": spread,
            "never_locks_share": never, "oscillation_period_s": period,
            "confidence": conf,
        },
    }


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--manifest", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--delta-fine", type=float, default=0.25)
    ap.add_argument("--span", type=float, default=10.0)
    ap.add_argument("--pad", type=float, default=2.0)
    ap.add_argument("--seed", type=int, default=20260903)
    args = ap.parse_args()

    manifest = load_manifest(args.manifest)
    for k, name in enumerate(sorted(STANDIN_SPECS)):
        df = build_one(manifest, name, args.delta_fine, args.span, args.pad,
                       args.seed + 101 * k)
        path = os.path.join(args.out, name)
        os.makedirs(path, exist_ok=True)
        df.to_csv(os.path.join(path, "answers.csv"), index=False)
        try:
            import yaml

            with open(os.path.join(path, "system_card.yaml"), "w", encoding="utf-8") as fh:
                yaml.safe_dump(card(name), fh, sort_keys=True, allow_unicode=True)
        except Exception:
            pass
        print(f"wrote stand-in {name} -> {path} ({len(df)} rows)")


if __name__ == "__main__":
    main()
